// Irregular & high-frequency English lexicon sorted strictly in ASCII lexicographical order
// for O(log N) binary lookup via std::lower_bound with zero heap allocation at lookup time.
struct LexSyllable {
    const char* disp;
    const char* onset;
    VowelId v1;
    VowelId v2;
    bool diph;
    const char* coda;
};

struct LexWord {
    const char* word;
    uint8_t count;
    uint8_t stressedIdx;
    LexSyllable sylls[4];
};

