inline constexpr size_t kEnglishLexiconSize = sizeof(kEnglishLexicon) / sizeof(kEnglishLexicon[0]);

inline const LexWord* findEnglishLexiconWord(const std::string& w) {
    const LexWord* begin = kEnglishLexicon;
    const LexWord* end = kEnglishLexicon + kEnglishLexiconSize;
    const LexWord* it = std::lower_bound(begin, end, w, [](const LexWord& entry, const std::string& key) {
        return std::strcmp(entry.word, key.c_str()) < 0;
    });
    if (it != end && std::strcmp(it->word, w.c_str()) == 0) {
        return it;
    }
    return nullptr;
}

